#include "ui_scene_fixture_decode.hpp"
#include <iostream>
using namespace mfrk::ui::scene;using namespace mfrk::ui::scene::test;
struct Case {std::string text;Constants values;StringConstants strings;bool positive,strict,selected,otherwise;};
int main(int argc,char**argv)try{if(argc!=2)throw std::runtime_error("fixture required");auto&id=identity("controls");auto r=Reader::file(argv[1],id);std::vector<Case>cases;for(unsigned c=0;c<id.count;++c){Case x;x.text=string(r);auto n=r.u32();if(n>256)throw std::runtime_error("constant bound");while(n--){auto key=string(r);const auto value=r.f64();const auto bits=std::bit_cast<std::uint64_t>(value);if((bits&0x7ff0000000000000ull)==0x7ff0000000000000ull&&(bits&0xfffffffffffffull)!=0&&(bits&0x8000000000000ull)==0)throw std::runtime_error("signalingNaN outsideprofile");if(!x.values.emplace(key,value).second)throw std::runtime_error("duplicate constant");}x.strings=strings(r);x.positive=r.flag();x.strict=r.flag();x.selected=r.flag();x.otherwise=r.flag();cases.push_back(std::move(x));}r.end();unsigned bad=0;for(const auto&x:cases){try{Attributes a{{"constant",x.text}};if(x.positive)a.emplace_back("positive_or_negative","true");const bool actual=select_if(a,x.values,x.strings,x.strict);if(actual!=x.selected||!actual!=x.otherwise){if(bad<5)std::cerr<<"case "<<(&x-cases.data())<<" "<<x.text<<'\n';++bad;}}catch(const std::exception&e){if(bad<5)std::cerr<<e.what()<<'\n';++bad;}}std::cout<<cases.size()<<" original control decisions, "<<bad<<" mismatches\n";return bad?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}
